challenge.solution:
def install(envs, env, package, version):
    if env not in envs:
        envs[env] = {}
    envs[env][package] = version

envs = {"game": {}}
install(envs, "game", "pygame", "2.5.2")
install(envs, "site", "flask", "3.0.0")
print(envs)
